package dev.saffron;

import java.util.*;
import java.nio.charset.StandardCharsets;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import static org.springframework.http.HttpStatus.*;

@Service class Aftercare {
 private final JdbcTemplate db;private final PaymentOperations payments;private final NotificationInbox inbox;private final java.time.Duration responseTime;
 Aftercare(JdbcTemplate db,PaymentOperations payments,NotificationInbox inbox,@org.springframework.beans.factory.annotation.Value("${support.escalation-after:PT24H}")String responseTime){this.db=db;this.payments=payments;this.inbox=inbox;this.responseTime=escalationDuration(responseTime);}
 static java.time.Duration escalationDuration(String value){var d=java.time.Duration.parse(value);if(d.compareTo(java.time.Duration.ofMinutes(5))<0||d.compareTo(java.time.Duration.ofDays(7))>0)throw new IllegalArgumentException("Support response deadline must be 5 minutes to 7 days");return d;}
 private Map<String,Object> ticketRow(UUID id){return db.queryForMap("select * from support_tickets where id=?",id);}
 private Map<String,Object> reviewRow(UUID id){return db.queryForMap("select * from order_reviews where id=?",id);}
 private void revision(UUID id,String actor,String action){db.update("insert into review_revisions(review_id,version,rating,body,state,actor,action) select id,version,rating,body,state,?,? from order_reviews where id=?",actor,action,id);}
 record Ticket(String category,String message,long requestedRefund){}
 record Review(int rating,String body){}
 static String text(String value,int max){if(value==null||value.isBlank()||value.length()>max||value.codePoints().anyMatch(c->Character.isISOControl(c)&&c!='\n'&&c!='\t'))throw new IllegalArgumentException("Non-empty text required, up to "+max+" characters");return value.strip();}
 static void ticketInput(Ticket t){if(t==null||t.category==null||!Set.of("MISSING","DAMAGED","INCORRECT","OTHER").contains(t.category)||t.requestedRefund<0)throw new IllegalArgumentException("Valid issue category and refund amount required");text(t.message,3000);}
 static void reviewInput(Review r){if(r==null||r.rating<1||r.rating>5)throw new IllegalArgumentException("Rating must be 1–5");text(r.body,2000);}
 private void audit(String actor,String action,UUID id){db.update("insert into audit(actor,action,resource) values(?,?,?)",actor,action,id.toString());}
 private Map<String,Object> order(String subject,UUID id){var rows=db.queryForList("select * from orders where id=? and customer_name=? for update",id,subject);if(rows.isEmpty())throw new ResponseStatusException(NOT_FOUND);return rows.getFirst();}
 private Map<String,Object> lockTicket(String subject,boolean admin,UUID id){var rows=db.queryForList("select order_id from support_tickets where id=? and (? or customer_subject=?)",id,admin,subject);if(rows.isEmpty())throw new ResponseStatusException(NOT_FOUND);db.queryForMap("select id from orders where id=? for update",rows.getFirst().get("order_id"));return db.queryForMap("select * from support_tickets where id=? for update",id);}
 private void message(UUID ticket,String role,String body){db.update("insert into support_messages(id,ticket_id,author_role,body) values(?,?,?,?)",UUID.randomUUID(),ticket,role,text(body,3000));}
 @Transactional public Map<String,Object> create(String subject,UUID order,String key,Ticket input){ticketInput(input);if(key==null||!key.matches("[A-Za-z0-9-]{8,100}"))throw new IllegalArgumentException("Idempotency key required");var o=order(subject,order);
 String hash=WebhookSignature.digest((order+"\n"+input.category+"\n"+input.requestedRefund+"\n"+text(input.message,3000)).getBytes(StandardCharsets.UTF_8));
 var prior=db.queryForList("select * from support_tickets where customer_subject=? and idempotency_key=?",subject,key);if(!prior.isEmpty()){if(!hash.equals(prior.getFirst().get("fingerprint")))throw new ResponseStatusException(CONFLICT,"Ticket key reused with different content");return prior.getFirst();}
 if(!Set.of("DELIVERED","CANCELLED").contains(o.get("state")))throw new ResponseStatusException(CONFLICT,"After-order support opens after delivery or cancellation");
 if(input.requestedRefund>((Number)o.get("total")).longValue())throw new IllegalArgumentException("Requested refund exceeds order total");if(db.queryForObject("select count(*) from support_tickets where order_id=?",Integer.class,order)>0)throw new ResponseStatusException(CONFLICT,"This order already has a support thread");
 UUID id=UUID.randomUUID();db.update("insert into support_tickets(id,order_id,customer_subject,category,requested_refund,idempotency_key,fingerprint) values(?,?,?,?,?,?,?)",id,order,subject,input.category,input.requestedRefund,key,hash);db.update("update support_tickets set response_due_at=now()+make_interval(secs=>?) where id=?",responseTime.toSeconds(),id);message(id,"CUSTOMER",input.message);audit(subject,"SUPPORT_OPENED",id);inbox.support(ticketRow(id),"SUPPORT_OPENED",true,true);return ticketRow(id);
 }
 @Transactional public Map<String,Object> reply(String subject,boolean admin,UUID id,long version,String body){var t=lockTicket(subject,admin,id);if(((Number)t.get("version")).longValue()!=version)throw new ResponseStatusException(CONFLICT,"Thread changed; refresh before replying");if(!t.get("status").equals("OPEN"))throw new ResponseStatusException(CONFLICT,"Thread is closed");if(db.queryForObject("select count(*) from support_messages where ticket_id=?",Integer.class,id)>=199)throw new ResponseStatusException(CONFLICT,"Thread reply limit reached; administrator can still resolve");message(id,admin?"ADMIN":"CUSTOMER",body);db.update("update support_tickets set version=version+1,updated_at=now() where id=?",id);audit(subject,"SUPPORT_REPLIED",id);inbox.support(ticketRow(id),"SUPPORT_REPLIED",admin,!admin);return Map.of("version",version+1);}
 @Transactional public Map<String,Object> decide(String actor,UUID id,long version,String decision,String note){text(note,3000);if(!Set.of("REFUND","RESOLVE").contains(decision==null?"":decision))throw new IllegalArgumentException("Decision must be REFUND or RESOLVE");var t=lockTicket(actor,true,id);if(((Number)t.get("version")).longValue()!=version||!t.get("status").equals("OPEN"))throw new ResponseStatusException(CONFLICT,"Thread changed or closed; refresh before deciding");UUID refund=null;
 if(decision.equals("REFUND")){long amount=((Number)t.get("requested_refund")).longValue();if(amount<1)throw new ResponseStatusException(CONFLICT,"No monetary refund requested");var r=payments.requestRefund((UUID)t.get("order_id"),"support-"+id,amount,"Support request "+id,actor);refund=(UUID)r.get("id");}
 message(id,"ADMIN",note);db.update("update support_tickets set status=?,refund_id=?,escalation_state=case when escalation_state='NONE' then 'NONE' else 'COMPLETED' end,version=version+1,updated_at=now() where id=?",refund==null?"RESOLVED":"REFUND_APPROVED",refund,id);audit(actor,"SUPPORT_"+decision,id);inbox.support(ticketRow(id),"SUPPORT_"+decision,true,false);return ticketRow(id);
 }
 @Transactional public Map<String,Object> review(String subject,UUID order,Review input){reviewInput(input);var o=order(subject,order);if(!o.get("state").equals("DELIVERED"))throw new ResponseStatusException(CONFLICT,"Only delivered orders can be reviewed");var old=db.queryForList("select * from order_reviews where order_id=?",order);if(!old.isEmpty()){var r=old.getFirst();if(((Number)r.get("rating")).intValue()!=input.rating||!r.get("body").equals(text(input.body,2000)))throw new ResponseStatusException(CONFLICT,"An order can be reviewed once");return r;}
 UUID id=UUID.randomUUID();db.update("insert into order_reviews(id,order_id,restaurant_id,customer_subject,rating,body) values(?,?,?,?,?,?)",id,order,o.get("restaurant_id"),subject,input.rating,text(input.body,2000));audit(subject,"REVIEW_CREATED",id);revision(id,subject,"CREATED");inbox.review(reviewRow(id),"REVIEW_CREATED",false);return reviewRow(id);}
 @Transactional public Object moderate(String actor,UUID id,long version,boolean hidden,String reason){text(reason,500);var rows=db.queryForList("select * from order_reviews where id=? for update",id);if(rows.isEmpty())throw new ResponseStatusException(NOT_FOUND);if(((Number)rows.getFirst().get("version")).longValue()!=version)throw new ResponseStatusException(CONFLICT,"Review changed; refresh");db.update("update order_reviews set state=?,version=version+1 where id=?",hidden?"HIDDEN":"PUBLISHED",id);audit(actor,hidden?"REVIEW_HIDDEN":"REVIEW_RESTORED",id);db.update("insert into review_moderation(id,review_id,actor,reason,hidden) values(?,?,?,?,?)",UUID.randomUUID(),id,actor,text(reason,500),hidden);revision(id,actor,hidden?"HIDDEN":"RESTORED");inbox.review(reviewRow(id),hidden?"REVIEW_HIDDEN":"REVIEW_RESTORED",false);return Map.of("version",version+1);}
 @Transactional public Object editReview(String subject,UUID order,long version,Review input){reviewInput(input);order(subject,order);var rows=db.queryForList("select * from order_reviews where order_id=? for update",order);if(rows.isEmpty())throw new ResponseStatusException(NOT_FOUND);var r=rows.getFirst();if(((Number)r.get("version")).longValue()!=version)throw new ResponseStatusException(CONFLICT,"Review changed; refresh before editing");if(((Number)r.get("rating")).intValue()==input.rating&&r.get("body").equals(text(input.body,2000)))return r;UUID id=(UUID)r.get("id");db.update("update order_reviews set rating=?,body=?,version=version+1 where id=?",input.rating,text(input.body,2000),id);revision(id,subject,"EDITED");audit(subject,"REVIEW_EDITED",id);inbox.review(reviewRow(id),"REVIEW_EDITED",true);return reviewRow(id);}
 @Transactional public Object escalate(String actor,boolean admin,UUID id,long version,String reason,boolean automatic){text(reason,1000);var t=lockTicket(actor,admin,id);if(((Number)t.get("version")).longValue()!=version||!t.get("status").equals("OPEN")||!t.get("escalation_state").equals("NONE"))throw new ResponseStatusException(CONFLICT,"Thread changed, closed or already escalated");if(automatic&&!Boolean.TRUE.equals(db.queryForObject("select response_due_at<=now() from support_tickets where id=?",Boolean.class,id)))throw new ResponseStatusException(CONFLICT,"Response deadline not reached");db.update("update support_tickets set escalation_state='REQUESTED',escalation_reason=?,escalated_by=?,escalated_at=now(),updated_at=now(),version=version+1 where id=?",text(reason,1000),actor,id);audit(actor,automatic?"SUPPORT_AUTO_ESCALATED":"SUPPORT_ESCALATED",id);inbox.support(ticketRow(id),"SUPPORT_ESCALATED",true,true);return ticketRow(id);}
 @Transactional public Object acknowledge(String actor,UUID id,long version,String note){text(note,1000);var t=lockTicket(actor,true,id);if(((Number)t.get("version")).longValue()!=version||!t.get("status").equals("OPEN")||!t.get("escalation_state").equals("REQUESTED"))throw new ResponseStatusException(CONFLICT,"Escalation changed or is not awaiting acknowledgment");db.update("update support_tickets set escalation_state='ACKNOWLEDGED',acknowledged_by=?,acknowledged_at=now(),acknowledgement=?,updated_at=now(),version=version+1 where id=?",actor,text(note,1000),id);audit(actor,"SUPPORT_ESCALATION_ACKNOWLEDGED",id);inbox.support(ticketRow(id),"SUPPORT_ACKNOWLEDGED",true,false);return ticketRow(id);}
 public List<Map<String,Object>> overdue(){return db.queryForList("select id,version from support_tickets where status='OPEN' and escalation_state='NONE' and response_due_at<=now() order by response_due_at limit 20");}

}
